def solve(nums):
    """
    Given an array nums of integers, return the length of the longest strictly increasing subsequence of nums.

    A subsequence is a selection of some (not necessarily contiguous)
    elements from the array.

    Args:
        nums (list): A list of integers.

    Returns:
        int: The length of the longest strictly increasing subsequence of nums.
    """
    tails = []
    for num in nums:
        if not tails or num > tails[-1]:
            tails.append(num)
        else:
            l, r = 0, len(tails) - 1
            while l <= r:
                mid = (l + r) // 2
                if tails[mid] < num:
                    l = mid + 1
                else:
                    r = mid - 1
            tails[l] = num
    return len(tails)
```

