def solve(grid, start, goal):
    """
    Finds a path between two cells of a grid.

    Args:
        grid: A list of equal-length strings with between 1 and 30 rows and between 1 and 30 columns.
              The character '.' is a free cell and the character '#' is a wall.
        start: A (row, col) tuple of 0-based indices.
        goal: A (row, col) tuple of 0-based indices.

    Returns:
        A list of (row, col) tuples that begins with start, ends with goal, and in which consecutive
        cells are neighbors and every cell is free.
    """
    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0

    if not grid or rows == 0 or cols == 0:
        return []

    if not (0 <= start[0] < rows and 0 <= start[1] < cols and grid[start[0]][start[1]] != '#'):
        return []
    if not (0 <= goal[0] < rows and 0 <= goal[1] < cols and grid[goal[0]][goal[1]] != '#'):
        return []

    if start == goal:
        return [start]

    def get_neighbors(row, col):
        neighbors = []
        for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            new_row, new_col = row + dr, col + dc
            if 0 <= new_row < rows and 0 <= new_col < cols and grid[new_row][new_col] != '#':
                neighbors.append((new_row, new_col))
        return neighbors

    queue = [(start, [start])]
    visited = {start}

    while queue:
        (row, col), path = queue.pop(0)

        if (row, col) == goal:
            return path

        for neighbor_row, neighbor_col in get_neighbors(row, col):
            if (neighbor_row, neighbor_col) not in visited:
                visited.add((neighbor_row, neighbor_col))
                queue.append(((neighbor_row, neighbor_col), path + [(neighbor_row, neighbor_col)]))

    return []
