        row, col = node
        neighbors = []
        rows = len(grid)
        cols = len(grid[0])

        possible_neighbors = [(row - 1, col), (row + 1, col), (row, col - 1), (row, col + 1)]

        for r, c in possible_neighbors:
            if 0 <= r < rows and 0 <= c < cols and grid[r][c] != '#':
                neighbors.append((r, c))
        return neighbors

    def is_valid_move(node):
        row, col = node
        return 0 <= row < len(grid) and 0 <= col < len(grid[0]) and grid[row][col] != '#'

    def find_path(current_path, visited):
        current_node = current_path[-1]

        if current_node == goal:
            return current_path

        neighbors = get_neighbors(current_node)
        for neighbor in neighbors:
            if neighbor not in visited:
                new_path = current_path + [neighbor]
                new_visited = visited | {neighbor}
                result = find_path(new_path, new_visited)
                if result:
                    return result
        return None

    if not grid or not grid[0]:
        return []

    if not is_valid_move(start) or not is_valid_move(goal):
        return []

    if start == goal:
        if is_valid_move(start):
            return [start]
        else:
            return []

    path = find_path([start], {start})
    return path if path else []
