def solve(n, edges, s, t):
    if s == t:
        return 0

    graph = {i: [] for i in range(n)}
    for u, v, w in edges:
        graph[u].append((v, w))

    visited = [False] * n
    path = []

    def dfs(node, current_path, current_weight):
        nonlocal path
        visited[node] = True
        current_path.append(node)

        if node == t:
            if not path or current_weight < path[0]:
                path = current_path[:]
            visited[node] = False
            current_path.pop()
            return

        for neighbor, weight in graph[node]:
            if not visited[neighbor]:
                dfs(neighbor, current_path, current_weight + weight)

        visited[node] = False
        current_path.pop()

    dfs(s, [], 0)

    if not path:
        return -1
    else:
        total_weight = 0
        for i in range(len(path) - 1):
            u = path[i]
            v = path[i+1]
            found = False
            for neighbor, weight in graph[u]:
                if neighbor == v:
                    total_weight += weight
                    found = True
                    break
            if not found:
                return -1
        return total_weight
